<?php require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/ui.php';requireProfile($conn);$uid=(int)$_SESSION['user_id'];$filter=$_GET['type']??'ALL';$where='r.user_id=?';$types='i';$params=[$uid];if(in_array($filter,['LOST','FOUND'])){$where.=' AND r.type=?';$types.='s';$params[]=$filter;}$sql="SELECT r.id,r.type,r.item_name,r.image,r.incident_date,r.status,r.description,c.name category_name,l.name location_name FROM reports r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN locations l ON l.id=r.location_id WHERE $where ORDER BY r.created_at DESC";$st=$conn->prepare($sql);$st->bind_param($types,...$params);$st->execute();$rows=$st->get_result();$titleForTop='Laporan Saya';renderHead('Laporan Saya');renderUserNav('laporan');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Laporan Saya</h1><p class="muted">Semua laporan barang hilang dan barang ditemukan milikmu.</p></div><a class="btn btn-primary" href="buat-laporan.php">＋ Buat Laporan</a></div><?php if(isset($_GET['success'])): ?><div class="notice notice-ok">Laporan berhasil dibuat dan menunggu verifikasi admin.</div><?php endif; ?><div class="actions" style="margin:0 0 18px"><a class="btn <?= $filter==='ALL'?'btn-primary':'btn-light' ?>" href="laporan.php">Semua</a><a class="btn <?= $filter==='LOST'?'btn-primary':'btn-light' ?>" href="laporan.php?type=LOST">Barang Hilang</a><a class="btn <?= $filter==='FOUND'?'btn-primary':'btn-light' ?>" href="laporan.php?type=FOUND">Barang Ditemukan</a></div><div class="grid grid-3 stagger"><?php if($rows->num_rows): while($r=$rows->fetch_assoc()): ?><a class="card item-card" href="detail-barang.php?id=<?= $r['id'] ?>"><div class="thumb"><?php if($r['image']): ?><img src="uploads/<?= e($r['image']) ?>" alt="<?= e($r['item_name']) ?>"><?php else: ?>📦<?php endif; ?></div><div class="body"><span class="pill <?= $r['type']==='FOUND'?'pill-green':'pill-red' ?>"><?= $r['type']==='FOUND'?'BARANG DITEMUKAN':'BARANG HILANG' ?></span><h3><?= e($r['item_name']) ?></h3><div class="meta"><?= e($r['category_name']??'-') ?> · <?= e($r['location_name']??'-') ?><br><?= e($r['incident_date']) ?></div><p class="meta"><?= e(mb_strimwidth($r['description'],0,90,'...')) ?></p><span class="pill pill-yellow"><?= e(statusLabel($r['status'])) ?></span></div></a><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Belum ada laporan pada filter ini.</div><?php endif; ?></div></div><?php renderFooter(); ?>
